39	
40	public:
41	    Optional() {}
42	    Optional(T d) :_isSet(true), _data(d) {}
43	    Optional(const Optional &t) : _isSet(t._isSet), _data(t._data) {}
44	
45	    //bool isNull()       const { return !_isSet; }
46	    //bool isDefineded()  const { return _isSet; }
47	    //bool isEmpty()      const { return !_isSet; }
48	
49	    T    get()          const { CCASSERT(_isSet, "data should be set!"); return _data; }
50	    void set(T d)             { _isSet = true; _data = d; }
51	
52	private:
53	    bool _isSet = false;
54	    T _data;
55	};
