77	#if (defined(__GNUC__) && __GNUC__ >= 4) || defined(__clang__)
78	#define LIKELY(x)   (__builtin_expect((x), 1))
79	#define UNLIKELY(x) (__builtin_expect((x), 0))
80	#else
81	#define LIKELY(x)   (x)
82	#define UNLIKELY(x) (x)
83	#endif
